-- ============================================================
-- 163_sign_option_lists.sql
--
-- Doc Sign: shared option lists (feature F-96). A list is a named, reusable set of choices (the states of Malaysia, the
-- banks, the MSIC business activity codes) kept once in Settings > Doc Sign > Lists. A data field of a form can name a list
-- instead of carrying its own options; the list's items are copied into the form when a template version is saved and
-- when a document is made or sent, so a document that is already out is never changed by a later edit of a list.
--
--   sign_option_list_defaults() the lists shipped with the product (product data, a function, not a table): the 13 states
--                               and 3 federal territories, countries, banks, company ID types, e-invoice phases, tax types,
--                               and MSIC 2008 (1,174 five-digit codes, DOSM). Generated from
--                               src/lib/sign/lists/system-lists.ts; a test fails when this file drifts from it.
--   sign_option_lists           each workspace's lists: its copy of the system lists (labels editable, items addable, values
--                               never deleted) and any list the workspace made itself. One JSON array of items per list.
--   sign_option_lists_guard()   what the table cannot say alone: a key, kind and "system" flag never change; a system list
--                               never loses an item; values are unique and well formed; the list's version moves on every change.
--   sign_seed_option_lists()    copy the shipped lists into a workspace (idempotent), called by sign_ensure_defaults and,
--                               here, for every workspace that already uses Doc Sign.
--   sign_template_versions.form / sign_documents.form_snapshot   the size limit rises from 400 KB to 2 MB: a form that
--                               names the MSIC list carries its ~200 KB of options (copied in so the document is self-contained).
--
-- Reading follows menu.sign; writing by people follows sign.settings (the server writes with the service role).
-- A list is archived, never deleted. Idempotent.
-- ============================================================

-- ------------------------------------------------------------
-- 1. A workspace's lists
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.sign_option_lists (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id  UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,
  -- Stable and fixed (for example states_my): a form names a list by this.
  key         TEXT NOT NULL CHECK (key ~ '^[a-z][a-z0-9_]{1,40}$'),
  name        TEXT NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 120),
  description TEXT CHECK (description IS NULL OR length(description) <= 500),
  kind        TEXT NOT NULL DEFAULT 'options' CHECK (kind IN ('options', 'msic')),
  -- [{ "value": "johor", "label": { "en": "Johor", "ms": "Johor" }, "group": "...", "archived": true }]
  items       JSONB NOT NULL DEFAULT '[]'::jsonb
              CHECK (jsonb_typeof(items) = 'array' AND jsonb_array_length(items) <= 5000 AND pg_column_size(items) <= 2000000),
  -- How many items, so a screen can list the lists without reading all their items.
  item_count  INTEGER GENERATED ALWAYS AS (jsonb_array_length(items)) STORED,
  is_system   BOOLEAN NOT NULL DEFAULT FALSE,
  version     INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  archived    BOOLEAN NOT NULL DEFAULT FALSE,
  -- The person who made the last change (the server writes with the service role, so the audit trail credits this person).
  updated_by  UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT sign_option_lists_key UNIQUE (account_id, key)
);
CREATE INDEX IF NOT EXISTS sign_option_lists_account_idx ON public.sign_option_lists (account_id, archived);

ALTER TABLE public.sign_option_lists ENABLE ROW LEVEL SECURITY;

-- The API roles: signed-in people read and write under the policies below; nothing for a signed-out caller.
REVOKE ALL ON public.sign_option_lists FROM PUBLIC, anon;
GRANT SELECT, INSERT, UPDATE ON public.sign_option_lists TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sign_option_lists TO service_role;

DROP POLICY IF EXISTS sign_option_lists_select ON public.sign_option_lists;
DROP POLICY IF EXISTS sign_option_lists_insert ON public.sign_option_lists;
DROP POLICY IF EXISTS sign_option_lists_update ON public.sign_option_lists;
CREATE POLICY sign_option_lists_select ON public.sign_option_lists
  FOR SELECT USING (has_capability(account_id, 'menu.sign'));
-- A person makes ordinary lists only; the system lists come from sign_seed_option_lists().
CREATE POLICY sign_option_lists_insert ON public.sign_option_lists
  FOR INSERT WITH CHECK (has_capability(account_id, 'sign.settings') AND NOT is_system AND kind = 'options');
CREATE POLICY sign_option_lists_update ON public.sign_option_lists
  FOR UPDATE USING (has_capability(account_id, 'sign.settings'))
  WITH CHECK (has_capability(account_id, 'sign.settings'));
-- No delete: a list is archived, so a form that names it keeps working.

-- ------------------------------------------------------------
-- 2. updated_at, audit, and the rules the table cannot state alone
-- ------------------------------------------------------------
DROP TRIGGER IF EXISTS set_updated_at ON public.sign_option_lists;
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.sign_option_lists
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

DROP TRIGGER IF EXISTS audit_row_change ON public.sign_option_lists;
CREATE TRIGGER audit_row_change
  AFTER INSERT OR UPDATE OR DELETE ON public.sign_option_lists
  FOR EACH ROW EXECUTE FUNCTION public.audit_row_change(
    'sign_option_list', 'name', 'name,archived,version', 'description,items', '', 'updated_by');

CREATE OR REPLACE FUNCTION public.sign_option_lists_guard()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_gone TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- the system lists are made by sign_seed_option_lists, which says so for the length of its own transaction; nothing a
    -- person or the app can call can set that, so no API role can make a list that claims to be one of ours
    IF NEW.is_system AND COALESCE(current_setting('vircle.seeding_option_lists', true), '') <> 'on' THEN
      RAISE EXCEPTION 'sign_option_list_system_is_seeded' USING ERRCODE = '42501';
    END IF;
    -- a list of the workspace's own may not take a key a shipped list uses, or that list could never be seeded
    IF NOT NEW.is_system AND EXISTS (SELECT 1 FROM public.sign_option_list_defaults() d WHERE d.key = NEW.key) THEN
      RAISE EXCEPTION 'sign_option_list_key_is_reserved' USING ERRCODE = '23505',
        DETAIL = 'That key belongs to a list that comes with Doc Sign.';
    END IF;
  ELSE
    IF NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.key IS DISTINCT FROM OLD.key
       OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.is_system IS DISTINCT FROM OLD.is_system THEN
      RAISE EXCEPTION 'sign_option_list_identity_is_fixed' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF TG_OP = 'INSERT' OR NEW.items IS DISTINCT FROM OLD.items THEN
    IF jsonb_typeof(NEW.items) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'sign_option_list_items_must_be_an_array' USING ERRCODE = '23514';
    END IF;
    -- every item has a well-formed, unique value and an English label
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(NEW.items) o
       WHERE jsonb_typeof(o) <> 'object'
          OR COALESCE(o ->> 'value', '') !~ '^[A-Za-z0-9][A-Za-z0-9_.\-]{0,59}$'
          OR btrim(COALESCE(o #>> '{label,en}', '')) = ''
    ) THEN
      RAISE EXCEPTION 'sign_option_list_item_is_not_valid' USING ERRCODE = '23514';
    END IF;
    IF (SELECT count(DISTINCT o ->> 'value') FROM jsonb_array_elements(NEW.items) o) <> jsonb_array_length(NEW.items) THEN
      RAISE EXCEPTION 'sign_option_list_duplicate_values' USING ERRCODE = '23505';
    END IF;
    IF NEW.kind = 'msic' AND EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.items) o WHERE (o ->> 'value') !~ '^[0-9]{5}$') THEN
      RAISE EXCEPTION 'sign_option_list_msic_code_is_not_valid' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- a system list keeps every value it had: answers and forms depend on them
    IF OLD.is_system AND NEW.items IS DISTINCT FROM OLD.items THEN
      SELECT string_agg(x.v, ', ') INTO v_gone FROM (
        SELECT o ->> 'value' AS v FROM jsonb_array_elements(OLD.items) o
        EXCEPT
        SELECT n ->> 'value' FROM jsonb_array_elements(NEW.items) n
      ) x;
      IF v_gone IS NOT NULL THEN
        RAISE EXCEPTION 'sign_option_list_system_values_cannot_be_deleted' USING ERRCODE = '23514',
          DETAIL = left(v_gone, 300);
      END IF;
    END IF;
    IF NEW.items IS DISTINCT FROM OLD.items OR NEW.name IS DISTINCT FROM OLD.name THEN
      NEW.version := OLD.version + 1;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
ALTER FUNCTION public.sign_option_lists_guard() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.sign_option_lists_guard() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS sign_option_lists_guard ON public.sign_option_lists;
CREATE TRIGGER sign_option_lists_guard
  BEFORE INSERT OR UPDATE ON public.sign_option_lists
  FOR EACH ROW EXECUTE FUNCTION public.sign_option_lists_guard();

-- ------------------------------------------------------------
-- 3. A form that names a big list carries its options: room for them
-- ------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'sign_template_versions_form_object') THEN
    ALTER TABLE public.sign_template_versions DROP CONSTRAINT sign_template_versions_form_object;
  END IF;
  ALTER TABLE public.sign_template_versions
    ADD CONSTRAINT sign_template_versions_form_object CHECK (form IS NULL OR (jsonb_typeof(form) = 'object' AND pg_column_size(form) <= 2000000));
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'sign_documents_form_object') THEN
    ALTER TABLE public.sign_documents DROP CONSTRAINT sign_documents_form_object;
  END IF;
  ALTER TABLE public.sign_documents
    ADD CONSTRAINT sign_documents_form_object CHECK (form_snapshot IS NULL OR (jsonb_typeof(form_snapshot) = 'object' AND pg_column_size(form_snapshot) <= 2000000));
END $$;

-- ------------------------------------------------------------
-- 4. The shipped lists (a function: product data, not tenant data)
-- ------------------------------------------------------------
