  ('einvoice_phases'::text, 'E-invoice phases by turnover'::text, 'When a business must start e-invoicing, by yearly turnover.'::text, 'options'::text, $j$[{"value":"phase_1","label":{"en":"Phase 1: above RM100 million","ms":"Fasa 1: melebihi RM100 juta","zh":"第一阶段：超过1亿令吉","ko":"1단계: 1억 링깃 초과"}},{"value":"phase_2","label":{"en":"Phase 2: above RM25 million to RM100 million","ms":"Fasa 2: melebihi RM25 juta hingga RM100 juta","zh":"第二阶段：超过2500万至1亿令吉","ko":"2단계: 2,500만 링깃 초과 ~ 1억 링깃"}},{"value":"phase_3","label":{"en":"Phase 3: above RM5 million to RM25 million","ms":"Fasa 3: melebihi RM5 juta hingga RM25 juta","zh":"第三阶段：超过500万至2500万令吉","ko":"3단계: 500만 링깃 초과 ~ 2,500만 링깃"}},{"value":"phase_4","label":{"en":"Phase 4: above RM1 million to RM5 million","ms":"Fasa 4: melebihi RM1 juta hingga RM5 juta","zh":"第四阶段：超过100万至500万令吉","ko":"4단계: 100만 링깃 초과 ~ 500만 링깃"}},{"value":"not_required","label":{"en":"Not required: RM1 million or less","ms":"Tidak diwajibkan: RM1 juta atau kurang","zh":"无需：100万令吉或以下","ko":"해당 없음: 100만 링깃 이하"}}]$j$::jsonb, 1::integer, 5::integer),
