-- ------------------------------------------------------------
-- 5. Copying them into a workspace
-- ------------------------------------------------------------
-- Idempotent: a list the workspace already has (edited or not) is left exactly as it is. Returns how many lists it added.
CREATE OR REPLACE FUNCTION public.sign_seed_option_lists(p_account UUID)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_n INTEGER;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.accounts a WHERE a.id = p_account) THEN
    RAISE EXCEPTION 'account_not_found' USING ERRCODE = '22023';
  END IF;
  -- copying shipped content is not something anyone did: keep it out of the audit trail
  PERFORM set_config('vircle.audit_skip', 'on', true);
  PERFORM set_config('vircle.seeding_option_lists', 'on', true);
  INSERT INTO public.sign_option_lists (account_id, key, name, description, kind, items, is_system, version)
  SELECT p_account, d.key, d.name, d.description, d.kind, d.items, TRUE, 1
    FROM public.sign_option_list_defaults() d
   ORDER BY d.sort_order
  ON CONFLICT (account_id, key) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  PERFORM set_config('vircle.seeding_option_lists', 'off', true);
  PERFORM set_config('vircle.audit_skip', 'off', true);
  RETURN v_n;
END;
$$;
ALTER FUNCTION public.sign_seed_option_lists(UUID) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.sign_seed_option_lists(UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.sign_seed_option_lists(UUID) TO service_role;

-- The first time a workspace opens Doc Sign it gets its settings, its starting categories and now its lists.
-- (The app also asks for the lists directly whenever a form names a shipped list the workspace does not have yet,
-- so a later migration that redefines this function cannot leave a workspace without them.)
CREATE OR REPLACE FUNCTION public.sign_ensure_defaults(p_account UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  INSERT INTO public.sign_settings (account_id) VALUES (p_account)
  ON CONFLICT (account_id) DO NOTHING;

  INSERT INTO public.sign_categories (account_id, key, name, position) VALUES
    (p_account, 'merchant_agreements', 'Merchant agreements', 1),
    (p_account, 'nda',                 'NDA',                 2),
    (p_account, 'partnership',         'Partnership',         3),
    (p_account, 'sales',               'Sales',               4)
  ON CONFLICT (account_id, key) DO NOTHING;

  PERFORM public.sign_seed_option_lists(p_account);
END;
$$;
ALTER FUNCTION public.sign_ensure_defaults(UUID) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.sign_ensure_defaults(UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.sign_ensure_defaults(UUID) TO service_role;

-- Every workspace that already uses Doc Sign (it has a settings row) gets its lists now.
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN SELECT s.account_id FROM public.sign_settings s LOOP
    PERFORM public.sign_seed_option_lists(r.account_id);
  END LOOP;
END $$;

